    // Not available at 0x180, 0x500 and 0x514 (0x8000): condenser temp 0x0a37, heating curve 0x4f2b, flow temp after
    // DHC 0x4f40, DHC relays 0xb3be-0xb3c0, superheat 0x4fa1/0x4fa2, 0x4ef0/0x4ef1/0x4efb/0x4efd/0x4f06.
    // Defrost starts 0x0806 is stuck at 9999.
    // No new information at 0x500 (two runs on 2026-09-23): 0x06eb is always 30, also at 34 Hz, and 0x0aff follows
    // the high pressure (r = 0.996, about 22 * bar + 886), it is not the subcooling.

    // ABTAUUNGAKTIV 0x0061 at 0x500 (ha-stiebel-control) does not show the defrost: bit 9 (512) is set while the
    // compressor is requested or runs, bit 8 (256) shortly before the start, both unchanged during the defrosts on
    // 2026-09-25. The defrost is detected from the EXV opening and the evaporator temperature instead.
    // No finer flow / return temperature than 0x01d6 / 0x0016 (steps of about 1.1 K), tested on 2026-09-23:
    // 0x4f41 / 0x4f43 at 0x180, 0xfdf3 / 0xfdf4 at 0x700 and SAMMLERISTTEMP 0x000d at 0x180 answer 0x8000,
    // VORLAUFISTTEMP 0x000f at 0x180 is always -40 degC (no sensor). HEIZKURVE 0x010e at 0x180 is always 0.
    // VORLAUFISTTEMP_WP_IWS 0x0822 / RUECKLAUFISTTEMP_WP_IWS 0x0823 at 0x500 give the same values in the same steps.

