    public static short WAERMEERTRAG_2WE_HEIZ_SUM_MWH =  (short)0x0929;


    public ElsterTable(){
        inialize1();
        inialize2();
        initializeWpl17();
    }

    public ElsterIndex findByIndex(short index){
        ElsterIndex elsterIndex = elsterIndexHashMap.get(index);
        if ( elsterIndex == null){
            ByteBuffer buffer = ByteBuffer.allocate(2);
            buffer.putShort(index);

            elsterIndex = new ElsterIndex("UNKOWN_ELSTERINDEX_"+ ElsterMessage.bytesToHex(buffer.array()), index, ElsterType.et_default);
        }

        return elsterIndex;
    }

    private static void add(ElsterIndex elsterIndex) {
        elsterIndexHashMap.put(elsterIndex.getIndex(),elsterIndex);
    }
